import PsyanimMessaging from "./PsyanimMessaging.js";

export default class PsyanimAnimationClip {

    constructor(sampleData = []) {

        this._sampleData = sampleData;
    }

    static fromJson(data) {

        let clip = new PsyanimAnimationClip();

        clip._sampleData = JSON.parse(data);

        return clip;
    }

    getData(zeroInitialTimestamp = true) {

        if (zeroInitialTimestamp)
        {
            this.zeroInitialTimestamp();
        }

        // returns a deep copy
        return JSON.parse(JSON.stringify(this._sampleData));
    }

    zeroInitialTimestamp() {

        if (this._sampleData.length == 0)
        {
            console.error('No samples in data!');
            return;
        }

        let initialTimestamp = this._sampleData[0].t;

        // set first sample to exact 0 to avoid precision issues
        this._sampleData[0].t = 0;

        // subtract t0 from each sample thereafter
        for (let i = 1; i < this._sampleData.length; ++i)
        {
            this._sampleData[i].t -= initialTimestamp;
        }
    }

    addSample(time, position, rotation, optionalAttributes = {}) {

        this._sampleData.push({
            t: time,
            x: position.x,
            y: position.y,
            rotation: rotation,
            ...optionalAttributes
        });
    }

    clear() {

        this._sampleData = [];
    }

    getSample(index) {

        let sample = this._sampleData[index];

        // return a deep copy - should be fine for POJO data
        return JSON.parse(JSON.stringify(sample));
    }

    getSampleCount() {

        return this._sampleData.length;
    }
}